            if x == 1 or x == n - 1:
                continue
            for _ in range(s - 1):
                x = pow(x, 2, n)
                if x == n - 1:
                    break
            else:
                return False
        return True

    count = 0
    for i in range(l, r + 1):
        if is_prime(i):
            if i == 2 or i % 4 == 1:
                count += 1

    return str(count) + '\n'
