        parts = list(map(int, line.split()))
        k = parts[0]
        clause = parts[1:]
        clauses.append(clause)

    # Build implication graph for 2-SAT
    # Node 2*i represents ¬x_i, node 2*i+1 represents x_i (for variable x_i, i starting from 0)
    num_nodes = 2 * m
    adj = [[] for _ in range(num_nodes)]
    rev_adj = [[] for _ in range(num_nodes)]

    def add_implication(u, v):
        adj[u].append(v)
        rev_adj[v].append(u)

    def negate(node):
        return node ^ 1

    # Process each clause - standard 2-SAT implication conversion
    for clause in clauses:
        k = len(clause)
        if k == 0:
            return "NO\n" + ''.join(['0'] * m)

        # For clause (l1 ∨ l2 ∨ ... ∨ lk):
        # For each li, we need: ¬li → (l1 ∨ ... ∨ l_{i-1} ∨ l_{i+1} ∨ ... ∨ lk)
        # This breaks down to 2-SAT implications

        # For a 2-literal clause (l1 ∨ l2): ¬l1 → l2, ¬l2 → l1
        # For a 1-literal clause (l1): l1 must be true → ¬l1 → contradiction

        clique = list(clause)

        if k == 1:
            # Force this literal to be true
            lit = clique[0]
            x_idx = abs(lit) - 1  # 0-indexed variable index
            if lit > 0:
                # lit (x is true) must be true, so ¬lit → false
                # This means 2*0 (¬x) should lead to contradiction, but just mark as forced
                add_implication(2 * x_idx, 2 * x_idx)  # self-loop means required
            else:
                # -lit (x is false) must be true, so lit → false
                add_implication(2 * x_idx + 1, 2 * x_idx)  # x implies contradiction

        for i in range(k):
            lit_i = clique[i]

            # Get the negation of this literal
            if lit_i > 0:
                neg_node = 2 * (lit_i - 1)  # ¬x
            else:
                neg_node = 2 * (-lit_i - 1) + 1  # x_i for negative literal (lit is -k, so k is positive)

            if neg_node < 0:
                continue  # invalid

            # Get other literals
            other_lits = [l for j, l in enumerate(clique) if j != i]

            if len(other_lits) == 1:
                other_lit = other_lits[0]
                if other_lit > 0:
                    # other_lit is x_j, so node is 2*j
                    x_j = other_lit
                    # 0-indexed: node 2*(other_lit-1)
                    target = 2 * (other_lit - 1)
                    add_implication(neg_node, target)
                else:
                    other_lit = -other_lit
                    target = 2 * (other_lit - 1) + 1
                    add_implication(neg_node, target)
            elif len(other_lits) >= 2:
                # For more than 2 literals, naively add all implications
                # ¬lit_i → (l1 ∨ ... ∨ l_{i-1} ∨ l_{i+1} ∨ ... ∨ lk)
                # This becomes: ¬lit_i → l_j for all j ≠ i
                for other in other_lits:
                    if other > 0:
                        x_j = other
                        target = 2 * (x_j - 1)
                        add_implication(neg_node, target)
                    else:
                        other = -other
                        target = 2 * (other - 1) + 1
                        add_implication(neg_node, target)

    # Kosaraju's algorithm for SCC
    visited = [False] * num_nodes
    order = []

    def dfs1(node):
        visited[node] = True
        for nxt in adj[node]:
            if not visited[nxt]:
                dfs1(nxt)
        order.append(node)

    for i in range(num_nodes):
        if not visited[i]:
            dfs1(i)

    comp = [-1] * num_nodes
    comp_count = 0

    def dfs2(node, c):
        comp[node] = c
        for nxt in rev_adj[node]:
            if comp[nxt] == -1:
                dfs2(nxt, c)

    for i in range(num_nodes - 1, -1, -1):
        node = order[i]
        if comp[node] == -1:
            dfs2(node, comp_count)
            comp_count += 1

    # Check for contradictions: x and ¬x in same SCC
    for i in range(m):
        if comp[2 * i] == comp[2 * i + 1]:
            return "NO"

    # Build solution
    assignment = [0] * m
    for i in range(m):
        # If x_i (node 2*i+1) is in a different SCC from ¬x_i (node 2*i),
        # we should pick the one in the "topological order" (lower component index if processing reverse)
        # Actually, if comp[u] < comp[v], it means u must be true
        if comp[2 * i] < comp[2 * i + 1]:
            assignment[i] = 1  # x_i must be true
        else:
            assignment[i] = 0

    return "YES\n" + ''.join(map(str, assignment))

