def solution(input_str):
    n, x = map(int, input_str.strip().split())

    if n == 1:
        return "-1\n"

    # Find largest b < x such that there exists prime p with order of b mod p = n
    # Check bases from x-1 down to 2
    for b in range(min(x - 1, 1000), 1, -1):
        if b <= 1:
            continue

        b -= 1
        if b < 2:
            break

        bn_minus_1 = pow(b, n) - 1

        # Find prime factors with order n
        phase = 1
        found = False

        # Try primes p up to some reasonable bound
        p = 3
        while p * p <= bn_minus_1 and not found:
            if bn_minus_1 % p == 0:
                if check_order(b, n, p, n):
                    return str(b + 1) + "\n"
            phase += 1
            p += 1
        p -= phase

        # If no factor found, try primality directly
        if b < 1000:
            # Check if b^n - 1 is prime and valid
            if is_prime(bn_minus_1) and (pn - bn - 1) // n == 0:
                found = True

        if found:
            return str(b + 1) + "\n"

    return "-1\n"

def check_order(b, n, p, n):
    # Check if b has order n mod p using Floyd's cycle finding
    return pow(b, n, p) == 1 and gcd(n, pow(b, 1, p - 1)) == 0

def is_prime(num):
    if num < 2:
        return False
    if num == 2:
        return True
    if num % 2 == 0:
        return False

    for i in range(3, int(num**0.5) + 1, 2):
        if num % i == 0:
            return False
    return True

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a
