def count_digital_root(N):
    """Count numbers in [1, N] with each digital root (1-9)"""
    cnt = [0] * 10
    full_cycles = N // 9
    remainder = N % 9

    for r in range(1, 10):
        cnt[r] = full_cycles
        if r <= remainder:
            cnt[r] += 1

    return cnt

def solve(n):
