    cnt = count_digital_root(n)

    # Precompute digital root for products 1..9*9
    dr = [0] * 10
    for i in range(1, 10):
        if i % 9 != 0:
            dr[i] = i % 9
        else:
            dr[i] = 9

    # Also need d(d(a)*d(b))
    def digital_root_product(a, b):
        return (a * b - 1) % 9 + 1

    # Count all triples where d(A*B) = d(C)
    hash_count = 0
    for ra in range(1, 10):
        for rb in range(1, 10):
