    star_indices = [i for i, c in enumerate(field) if c == '*']

    if not pack_indices or not star_indices:
        return "0 0\n"

    m, k = len(pack_indices), len(star_indices)

    source = 0
    sink = m + k
    node_count = sink + 1

    capacity = [[0] * node_count for _ in range(node_count)]
    adj = [[] for _ in range(node_count)]

    for i in range(m):
        capacity[source][i] = 1
        adj[source].append(i)
        adj[i].append(source)

        for j in range(k):
            capacity[i][m + j] = 1
            adj[i].append(m + j)
            adj[m + j].append(i)

        capacity[m + i][sink] = 1
        adj[m + i].append(sink)
        adj[sink].append(m + i)

    max_flow = 0
    flow = [[0] * node_count for _ in range(node_count)]

    INF = float('inf')

    def bfs():
        q = [0]
        parent = [-1] * node_count
        parent[0] = -2
        level = [-1] * node_count
        level[0] = 0

        head = 0
        while head < len(q):
            u = q[head]
            head += 1
            if u == sink:
                break

            for v in range(node_count):
                if level[v] == -1 and capacity[u][v] > flow[u][v]:
                    level[v] = level[u] + 1
                    parent[v] = u
                    if level[v] < INF:
                        q.append(v)

        return parent[sink] != -1

    def dfs(u, pushed, parent, level):
        if pushed == 0 or u == sink:
            return pushed
        for v in range(node_count):
            if v not in adj[u] or level[v] != level[u] + 1 or flow[u][v] == capacity[u][v]:
                continue
            tr = dfs(v, min(pushed, capacity[u][v] - flow[u][v]), parent, level)
            if tr == 0:
                continue
            flow[u][v] += tr
            flow[v][u] -= tr
            return tr
        return 0

    while bfs():
        pushed = INF
        curr = sink
        while curr:
            parent[curr] = svc
            curr = [x for x in range(node_count) if capacity[x][curr] > flow[x][curr]]

        while pushed > 0:
            pushed -= min(pushed, min(capacity[i][curr] - flow[i][curr] for i in range(node_count) if capacity[i][curr] > flow[i][curr]))

        for i in range(node_count):
            if capacity[i][curr] > flow[i][curr]:
                flow[i][curr] += pushed
                flow[curr][i] -= pushed

        max_flow += pushed

    if max_flow == 0:
        return "0 0\n"

    match = [-1] * m

    for i in range(m):
        for j in range(k):
