Looking at this problem, I need to determine if a car can return to its starting intersection with the odometer showing 0.

**Key Insight:**
1. The odometer resets to 0 when it reaches t_i, so the display shows distance mod t_i
2. For the odometer to show 0 at the end, the total distance traveled D must satisfy: (s_i + D) mod t_i == 0
3. The car can only travel within cycles reachable from its starting node
4. All achievable cycle lengths through a node are multiples of some g (the GCD of fundamental cycles)
5. Query (v, s, t) is achievable iff s is divisible by gcd(gcd_of_cycles_through_v, t)

**Algorithm:**
1. Use Tarjan's SCC algorithm to find strongly connected components (only nodes in the same SCC can reach each other and form cycles)
2. For each SCC, compute the GCD of all cycle lengths (fundamental cycles from back edges in DFS)
3. For each query, check if s % gcd(g, t) == 0

```python
# Your solution code
def solution(data):
    import sys
    from math import gcd

    sys.setrecursionlimit(400000)

    lines = data.strip().split('\n')
    if not lines:
        return ""

    n, m = map(int, lines[0].split())
    adj = [[] for _ in range(n + 1)]

    # Read edges
    for i in range(1, m + 1):
        a, b, l = map(int, lines[i].split())
        adj[a].append((b, l))

    q = int(lines[m + 1])
    queries = []
    # Read queries
    for i in range(q):
        v, s, t = map(int, lines[m + 2 + i].split())
        queries.append((v, s, t))

    # Tarjan's algorithm for SCC
    visited = [False] * (n + 1)
    disc = [-1] * (n + 1)
    low = [-1] * (n + 1)
    stack = []
    on_stack = [False] * (n + 1)
    scc_ids = [-1] * (n + 1)
    scc_count = 0
    idx = 0

    def tarjan(u):
        nonlocal idx, scc_count
        visited[u] = True
        disc[u] = low[u] = idx
        idx += 1
        stack.append(u)
        on_stack[u] = True

        for v, w in adj[u]:
            if not visited[v]:
                tarjan(v)
                low[u] = min(low[u], low[v])
            elif on_stack[v]:
                low[u] = min(low[u], disc[v])

        if low[u] == disc[u]:
            while True:
                node = stack.pop()
                on_stack[node] = False
                scc_ids[node] = scc_count
                if node == u:
                    break
            scc_count += 1

    # Get all SCCs
    for i in range(1, n + 1):
        if not visited[i]:
            tarjan(i)

    # Compute cycle GCD for each SCC
    scc_cycle_gcds = {}

    # For each SCC, DFS to find all back edge cycle lengths
    for scc in range(scc_count):
        if scc not in scc_cycle_gcds:
            # Get nodes in this SCC
            nodes = [u for u in range(1, n + 1) if scc_ids[u] == scc]

            dist = {}  # dist[u] = distance from DFS root to u
            g_val = 0

            for start_node in nodes:
                if start_node not in dist:
                    # Iterative DFS within this SCC
                    stack_dfs = [(start_node, 0)]
                    while stack_dfs:
                        u, d = stack_dfs.pop()
                        if u in dist:
                            continue
                        dist[u] = d
                        for v, w in adj[u]:
                            if scc_ids[v] == scc:
                                if v in dist:
                                    # Back edge found
                                    cycle_len = d + w - dist[v]
                                    g_val = gcd(g_val, cycle_len)
                                else:
                                    stack_dfs.append((v, d + w))

            if g_val == 0:
                scc_cycle_gcds[scc] = 0
            else:
                scc_cycle_gcds[scc] = g_val

    # Answer queries
    results = []
    for v, s, t in queries:
        if scc_ids[v] == -1:
            # Node is not reachable or not in any SCC (isolated)
            if s == 0:
                results.append("YES")
            else:
                results.append("NO")
        else:
            g = scc_cycle_gcds[scc_ids[v]]
            if g == 0:
                # No cycles through this node, but s=0 is valid
                if s == 0:
                    results.append("YES")
                else:
                    results.append("NO")
            else:
                # Check if s is divisible by gcd(g, t)
                common = gcd(g, t)
                if s % common == 0:
                    results.append("YES")
                else:
                    results.append("NO")

    return '\n'.join(results)
