    # Special case: n=1 with ai>=2 means GCD=ai>1 already
    if n == 1:
        return "0"

    INF = float('inf')

    def modify_cost(val, g):
        """Cost to make val divisible by g through: keep original, change ±1"""
        if val % g == 0:
            return 0
        if (val - 1) % g == 0 or (val + 1) % g == 0:
            return b
        return INF

    def solve_for_g(g):
        """Calculate min cost for a fixed divisor g"""

        cost_per_elem = [modify_cost(val, g) for val in arr]

        total_modifiable = sum(c for c in cost_per_elem if c != INF)
        if total_modifiable < INF:
            return total_modifiable

        # DP: dp[k] = min cost after processing 0..k-1 elements
        # INF means invalid state
        dp = [INF] * (n + 1)
        dp[0] = 0  # Base case: 0 elements processed, 0 cost

        for k in range(n):
            elem_cost = cost_per_elem[k]

            if elem_cost == INF:
                dp[k+1] = INF  # Cannot keep this element
            else:
                # Option 1: Keep this element (no removal started)
                dp[k+1] = dp[k] + elem_cost

            # Try removing segment [k, j] 
            for j in range(k, min(n - 1, n)):  # At most n-1 removals (don't remove whole array)
                # After removing [k, j], we need to process remaining
                break  # Single removal, continue

        # Let's use a cleaner DP approach
        # State tracking: not in removal, in removal, after removal
        not_in_removal = [0] * (n + 1)
        in_removal = [INF] * (n + 1)
        after_removal = [INF] * (n + 1)

        not_in_removal[0] = 0

        for k in range(n):
            c = cost_per_elem[k]
            if c == INF:
                # Cannot keep, only option is to remove
                if in_removal[k] != INF:
                    if k > 0 or j < n - 1:
                        after_removal[k+1] = min(after_removal[k+1], not_in_removal[k] + k * min_removal)
                continue

        # More straightforward approach
        INF = float('inf')
        cost_arr = [modify_cost(v, g) for v in arr]

        # Prefix sums for mod costs
        prefix = [0] * (n + 1)
        for i in range(n):
            prefix[i+1] = prefix[i] + (cost_arr[i] if cost_arr[i] != INF else INF)

        # Total cost if no removal (all modifications)
        total = sum(c for c in cost_arr if c != INF)
        if total < INF:
            return total

        # Find minimum by removing a segment
        for start in range(n):
            for end in range(start, min(n, n)):
                length = end - start + 1
                if length > n - 1:
                    break

                # Cost of segment being removed
                seg_cost = sum(cost_arr[start:end+1])

                # Cost of keeping remaining
                before_cost = sum(c for i, c in enumerate(cost_arr[:start]) if c != INF)
                after_cost = sum(c for i, c in enumerate(cost_arr[end+1:]) if c != INF)

                remaining = before_cost + after_cost
                if remaining != INF:
                    total_cost = remaining + length * a
                    return min(total_cost, total_cost if total < INF else INF)

        return INF

    # Get all prime factors
    factors = set()
    for val in arr:
        factors.add(val)
        # Get all prime factors of val
        d = 2
        temp = val
        while d * d <= temp:
            if temp % d == 0:
                factors.add(d)
                while temp % d == 0:
                    temp //= d
            d += 1
        if temp > 1:
            factors.add(temp)

    # Special handling for elements that can be fixed
    fixable_gcds = set()
    for val in arr:
        for g in range(2, int(val**0.5) + 2):
            if val % g in [0, 1]:
                fixable_gcds.add(g)
                break
        else:
            fixable_gcds.add(val)

    # Actually just use prime factors
    ans = INF
    for g in factors:
        if g < 2:
            continue
        cost = solve_for_g(g)
        if cost < INF:
            ans = min(ans, cost)

    return str(ans) if ans < INF else "0"
