        c = []
        for val in arr:
            if val % g == 0:
                c.append(0)
            elif (val + 1) % g == 0 or (val - 1) % g == 0:
                c.append(b)
            else:
                c.append(INF)

        if all(x < INF for x in c):
            return sum(c)

        ans = INF
        for i in range(n):
            for j in range(i, min(n - 1, n)):
                seg_invalid = sum(c[i:j+1]) >= INF
                if seg_invalid:
                    continue
                keep = sum(c[:i]) + sum(c[j+1:])
                if keep < INF:
                    ans = min(ans, keep + (j - i + 1) * a)

        return ans if ans < INF else INF

    ans = INF
    for g in all_factors:
        ans = min(ans, solve(g))

    return str(ans) if ans < INF else "0"
